        operatingHours,
      },
    ]);

    const branchByName = new Map(branches.map((branch) => [branch.name, branch]));

    const users = await User.insertMany([
      {
        name: "Priya Sharma",
        email: "priya.sharma@luminous.in",
        phone: "+91 98760 10001",
        role: "stylist",
        branchId: branchByName.get("Banjara Hills")?._id,
        commissionRate: 12,
