                  ) : (
                    <div className="w-8 h-8 rounded-full bg-[#16181F] flex items-center justify-center">
                      <span className="text-[10px] text-gray-400">
                        {staff.name
                          .split(' ')
                          .map((part) => part[0])
                          .join('')
                          .slice(0, 2)}
                      </span>
                    </div>
                  )
                ) : (
                  <div className="w-8 h-8 rounded-full bg-[#16181F] flex items-center justify-center">
                    <User className="w-4 h-4 text-gray-500" />
                  </div>
