                  </div>
                  <div className="flex items-center gap-3">
                    <User className="w-4 h-4 text-gray-400" />
                    <p className="text-sm text-gray-400">
                      {staffMembers.find((s) => s.id === selectedAppointment.staffId)?.name} (
