        whileHover={{ scale: 1.1 }}
        whileTap={{ scale: 0.95 }}
        onClick={() => setModalOpen(true)}
        className="fixed bottom-6 right-6 w-14 h-14 rounded-full bg-[#2563EB] text-white flex items-center justify-center shadow-lg z-30 border border-[#2563EB]/50"
