                <div>
                  <h5 className="text-xs font-semibold text-gray-400 uppercase tracking-wider mb-2">
                    Booking Notes
                  </h5>
                  <p className="text-sm text-white bg-[#0A0B0F] p-3 rounded-lg border border-white/5 italic">
                    &ldquo;{selectedAppointment.notes}&rdquo;
                  </p>
