// ─── NewBookingModal ────────────────────────────────────────────────────────

const EMPTY_SLOTS: { time: string; available: boolean; raw: string }[] = []

const BOOKING_CHANNELS = [
  { id: "web", label: "Web", Icon: Globe },
  { id: "whatsapp", label: "WhatsApp", Icon: MessageCircle },
  { id: "walkin", label: "Walk-in", Icon: User },
  { id: "call", label: "Call", Icon: Phone },
]

const SERVICE_CATEGORIES = ["All", "Hair", "Skin", "Nails", "Spa", "Packages"]

function generateDateChips() {
  const chips = []
  const today = new Date()
  const days = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"]
  for (let i = 0; i < 14; i++) {
    const d = new Date(today)
    d.setDate(today.getDate() + i)
    chips.push({
      label: `${days[d.getDay()]} ${d.getDate()}`,
      isToday: i === 0,
    })
  }
  return chips
}

interface NewBookingModalProps {
  open: boolean
  onClose: () => void
  services: any[]
  staff: Staff[]
  customers: any[]
  branchId: string | null
}

export function NewBookingModal({ open, onClose, services, staff, customers, branchId }: NewBookingModalProps) {
  const [step, setStep] = useState(1)
  const [selectedService, setSelectedService] = useState<string | null>(null)
  const [selectedCategory, setSelectedCategory] = useState("All")
  const [selectedStaff, setSelectedStaff] = useState(0)
  const [selectedDate, setSelectedDate] = useState(0)
  const [selectedSlot, setSelectedSlot] = useState<string | null>(null)
  const [selectedChannel, setSelectedChannel] = useState("whatsapp")
  const [waToggle, setWaToggle] = useState(true)
  const [selectedCustomer, setSelectedCustomer] = useState(0)
  const [slots, setSlots] = useState(EMPTY_SLOTS)
  const [slotsLoading, setSlotsLoading] = useState(false)
  const [slotsError, setSlotsError] = useState<string | null>(null)

  const dateChips = generateDateChips()
  const selectedServiceData = services.find((svc) => svc._id === selectedService)
  const selectedStaffData = staff[selectedStaff]
  const selectedCustomerData = customers[selectedCustomer]
  const selectedDateValue = (() => {
    const today = new Date()
    const date = new Date(today)
    date.setDate(today.getDate() + selectedDate)
    return date
  })()

  useEffect(() => {
    let active = true

    const fetchSlots = async () => {
      if (!branchId || !selectedService || !selectedStaffData) {
        setSlots([])
        return
      }

      try {
        setSlotsLoading(true)
        setSlotsError(null)
        const res = await fetch(
          `/api/appointments/slots?branchId=${branchId}&staffId=${selectedStaffData.id}&serviceId=${selectedService}&date=${selectedDateValue.toISOString()}`
        )

        if (!res.ok) {
          throw new Error('Failed to load slots')
        }

        const payload = await res.json()
        if (!active) return

        const normalized = (payload.data ?? []).map((slot: any) => {
          const time = new Date(slot.time)
          return {
            raw: slot.time,
            time: time.toLocaleTimeString('en-IN', { hour: 'numeric', minute: '2-digit' }),
            available: slot.available,
          }
        })

        setSlots(normalized)
      } catch (err) {
        if (active) {
          setSlotsError(err instanceof Error ? err.message : 'Failed to load slots')
        }
      } finally {
        if (active) {
          setSlotsLoading(false)
        }
      }
    }

    fetchSlots()
    return () => {
      active = false
    }
  }, [branchId, selectedService, selectedStaffData, selectedDateValue])

  const slotGroups = [
    {
      label: "Morning",
      slots: slots.filter((slot) => {
        const hour = new Date(slot.raw).getHours()
        return hour < 12
      }),
    },
    {
      label: "Afternoon",
      slots: slots.filter((slot) => {
        const hour = new Date(slot.raw).getHours()
        return hour >= 12 && hour < 17
      }),
    },
    {
      label: "Evening",
      slots: slots.filter((slot) => new Date(slot.raw).getHours() >= 17),
    },
  ]

  const handleClose = () => {
    onClose()
    // Reset after close animation
    setTimeout(() => {
      setStep(1)
      setSelectedService(null)
      setSelectedCategory("All")
      setSelectedStaff(0)
      setSelectedDate(0)
      setSelectedSlot(null)
      setSelectedChannel("whatsapp")
      setWaToggle(true)
      setSelectedCustomer(0)
      setSlots(EMPTY_SLOTS)
      setSlotsError(null)
    }, 300)
  }

  const serviceCategories = [
    "All",
    ...Array.from(
      new Set(services.map((svc) => svc.category?.charAt(0).toUpperCase() + svc.category?.slice(1)))
    ),
  ]
  const filteredServices = selectedCategory === "All"
    ? services
    : services.filter(
        (svc) => (svc.category?.charAt(0).toUpperCase() + svc.category?.slice(1)) === selectedCategory
      )

  const STEP_LABELS = ["Customer", "Service", "Schedule", "Confirm"]

  function StepSlot({ s }: { s: { time: string; available: boolean } }) {
    const active = selectedSlot === s.time
    if (!s.available) {
      return (
        <span className="bg-[#1C1F2A] text-gray-600 text-xs px-3 py-1.5 rounded-lg cursor-not-allowed line-through">
          {s.time}
        </span>
      )
    }
    return (
      <button
        onClick={() => setSelectedSlot(s.time)}
        className={`text-xs px-3 py-1.5 rounded-lg transition-colors ${
          active
            ? "bg-[#2563EB] text-white border border-[#2563EB]"
            : "bg-[#2563EB]/15 border border-[#2563EB]/40 text-[#2563EB] hover:bg-[#2563EB]/25"
        }`}
      >
        {s.time}
      </button>
    )
  }

  return (
    <AnimatePresence>
      {open && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          className="fixed inset-0 z-50 flex items-start justify-center backdrop-blur-xl bg-black/60 overflow-y-auto"
          onClick={(e) => e.target === e.currentTarget && handleClose()}
        >
          <motion.div
            initial={{ opacity: 0, y: 30, scale: 0.97 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 20, scale: 0.97 }}
            transition={{ type: "spring", damping: 28, stiffness: 300 }}
            className="relative w-full max-w-2xl mx-auto mt-12 mb-12 bg-[#16181F] rounded-2xl p-8 border border-white/5"
            style={{ boxShadow: "0 0 60px #2563EB15" }}
          >
            {/* Close */}
            <button
              onClick={handleClose}
              className="absolute top-4 right-4 w-8 h-8 rounded-full bg-white/5 flex items-center justify-center text-gray-400 hover:text-white transition-colors"
            >
              <X className="w-4 h-4" />
            </button>

            {/* Step Indicator */}
            <div className="flex items-center mb-8">
              {STEP_LABELS.map((label, i) => {
                const num = i + 1
                const isCompleted = step > num
                const isActive = step === num
                return (
                  <div key={label} className="flex items-center flex-1 last:flex-none">
                    <div className="flex flex-col items-center gap-1">
                      <div
                        className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-semibold transition-colors ${
                          isCompleted
                            ? "bg-[#2563EB] text-white"
                            : isActive
                            ? "bg-[#2563EB] text-white"
                            : "bg-[#1C1F2A] border border-white/10 text-gray-500"
                        }`}
                      >
                        {isCompleted ? <Check className="w-4 h-4" /> : num}
                      </div>
                      <span
                        className={`text-[10px] font-medium ${
                          isActive ? "text-white" : "text-gray-500"
                        }`}
                      >
                        {label}
                      </span>
                    </div>
                    {i < STEP_LABELS.length - 1 && (
                      <div
                        className={`flex-1 h-px mx-2 mb-4 transition-colors ${
                          step > num ? "bg-[#2563EB]" : "bg-white/10"
                        }`}
                      />
                    )}
                  </div>
                )
              })}
            </div>

            {/* Step Content */}
            <AnimatePresence mode="wait">
              <motion.div
                key={step}
                initial={{ opacity: 0, x: 20 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: -20 }}
                transition={{ duration: 0.2 }}
              >
                {/* STEP 1 — Customer */}
                {step === 1 && (
                  <div>
                    <h3 className="text-lg font-semibold text-white mb-4">Find Customer</h3>
                    <div className="relative">
                      <Phone className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-500" />
                      <input
                        type="tel"
                        placeholder="+91 Enter phone number"
                        className="w-full bg-[#0A0B0F] border border-white/10 focus:border-[#2563EB] outline-none rounded-xl pl-10 pr-4 py-3 text-white text-sm placeholder-gray-600 transition-colors"
                      />
                    </div>
                    {/* Customer result */}
                    {selectedCustomerData ? (
                      <div className="bg-[#1C1F2A] rounded-xl p-4 mt-3 flex items-center gap-4">
                        <div className="w-12 h-12 rounded-full bg-gradient-to-br from-blue-600 to-purple-600 flex items-center justify-center text-white font-bold flex-shrink-0">
                          {(selectedCustomerData.name ?? 'G')
                            .split(' ')
                            .map((part: string) => part[0])
                            .join('')
                            .slice(0, 2)}
                        </div>
                        <div className="flex-1 min-w-0">
                          <p className="font-semibold text-white">{selectedCustomerData.name ?? 'Guest'}</p>
                          <p className="text-sm text-gray-400">{selectedCustomerData.phone ?? ''}</p>
                          <div className="flex items-center gap-2 mt-1.5 flex-wrap">
                            <span className="text-[11px] px-2 py-0.5 rounded-full bg-amber-500/15 text-amber-400 font-medium border border-amber-500/20">
                              {String(selectedCustomerData.membershipTier ?? 'none').toUpperCase()}
                            </span>
                            <span className="text-[11px] text-gray-500">{selectedCustomerData.totalVisits ?? 0} visits</span>
                            <span className="text-[11px] px-2 py-0.5 rounded-full bg-[#2563EB]/15 text-[#2563EB] border border-[#2563EB]/20">
                              {selectedCustomerData.loyaltyPoints ?? 0} pts
                            </span>
                          </div>
                        </div>
                        <button
                          onClick={() => setSelectedCustomer((v) => (v + 1) % Math.max(customers.length, 1))}
                          className="ml-auto flex-shrink-0 text-sm text-[#2563EB] font-semibold hover:text-[#2563EB]/80 transition-colors"
                        >
                          Next →
                        </button>
                      </div>
                    ) : (
                      <div className="bg-[#1C1F2A] rounded-xl p-4 mt-3 text-sm text-gray-400">
                        No customers found.
                      </div>
                    )}
                  </div>
                )}

                {/* STEP 2 — Service */}
                {step === 2 && (
                  <div>
                    <h3 className="text-lg font-semibold text-white mb-4">Select Service</h3>
                    {/* Category tabs */}
                    <div className="flex gap-2 mb-4 flex-wrap">
                      {serviceCategories.map((cat) => (
                        <button
                          key={cat}
                          onClick={() => setSelectedCategory(cat)}
                          className={`px-3 py-1.5 rounded-lg text-sm transition-colors ${
                            selectedCategory === cat
                              ? "bg-[#2563EB] text-white"
                              : "text-gray-400 hover:text-white"
                          }`}
                        >
                          {cat}
                        </button>
                      ))}
                    </div>
                    {/* Service grid */}
                    <div className="grid grid-cols-3 gap-3">
                      {filteredServices.map((svc) => {
                        const isSelected = selectedService === svc._id
                        return (
                          <button
                            key={svc._id}
                            onClick={() => setSelectedService(svc._id)}
                            className={`relative bg-[#1C1F2A] rounded-xl p-4 text-left cursor-pointer border transition-colors ${
                              isSelected
                                ? "border-[#2563EB]"
                                : "border-white/5 hover:border-[#2563EB]/40"
                            }`}
                          >
                            {isSelected && (
                              <Check className="absolute top-2 right-2 w-4 h-4 text-[#2563EB]" />
                            )}
                            <p className="font-medium text-white text-sm mb-2">{svc.name}</p>
                            <div className="flex items-center gap-2">
                              <span className="text-xs bg-[#0A0B0F] px-2 py-0.5 rounded text-gray-400">
                                {svc.duration} min
                              </span>
                              <span className="text-xs font-semibold text-[#2563EB] ml-auto">
                                ₹{svc.price}
                              </span>
                            </div>
                          </button>
                        )
                      })}
                    </div>
                  </div>
                )}

                {/* STEP 3 — Schedule */}
                {step === 3 && (
                  <div>
                    <h3 className="text-lg font-semibold text-white mb-4">Schedule</h3>

                    {/* Staff */}
                    <p className="text-sm text-gray-400 mb-2">Select Staff</p>
                    <div className="flex gap-3 pb-2 overflow-x-auto">
                      {staff.map((staffItem, idx) => (
                        <button
                          key={staffItem.id}
                          onClick={() => setSelectedStaff(idx)}
                          className={`flex-shrink-0 w-20 text-center rounded-xl p-2 transition-colors ${
                            selectedStaff === idx
                              ? "border border-[#2563EB] bg-[#2563EB]/5"
                              : "border border-transparent"
                          }`}
                        >
                          <div className="w-10 h-10 mx-auto rounded-full bg-gradient-to-br from-blue-600 to-purple-600 flex items-center justify-center text-white text-xs font-bold">
                            {staffItem.name
                              .split(' ')
                              .map((part) => part[0])
                              .join('')
                              .slice(0, 2)}
                          </div>
                          <p className="text-xs mt-1 text-white truncate">{staffItem.name}</p>
                        </button>
                      ))}
                    </div>

                    {/* Date */}
                    <p className="text-sm text-gray-400 mt-4 mb-2">Select Date</p>
                    <div className="flex gap-2 pb-2 overflow-x-auto">
                      {dateChips.map((chip, idx) => (
                        <button
                          key={chip.label}
                          onClick={() => setSelectedDate(idx)}
                          className={`flex-shrink-0 rounded-lg px-3 py-2 text-xs transition-colors ${
                            selectedDate === idx
                              ? "bg-[#2563EB] text-white"
                              : "bg-[#1C1F2A] text-gray-400 hover:text-white"
                          }`}
                        >
                          {chip.label}
                        </button>
                      ))}
                    </div>

                    {/* Time slots */}
                    <p className="text-sm text-gray-400 mt-4 mb-2">Available Times</p>
                    <div className="space-y-3">
                      {slotsError && (
                        <div className="text-xs text-red-400">{slotsError}</div>
                      )}
                      {slotGroups.map(({ label, slots }) => (
                        <div key={label}>
                          <p className="text-xs text-gray-500 mb-2">{label}</p>
                          <div className="flex flex-wrap gap-2">
                            {slotsLoading && slots.length === 0 ? (
                              <div className="h-6 w-32 rounded-md bg-white/5 animate-pulse" />
                            ) : (
                              slots.map((s) => <StepSlot key={s.time} s={s} />)
                            )}
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {/* STEP 4 — Confirm */}
                {step === 4 && (
                  <div>
                    <h3 className="text-lg font-semibold text-white mb-4">Confirm Booking</h3>

                    {/* Summary */}
                    <div className="bg-[#0A0B0F] rounded-xl p-5 space-y-3">
                      {[
                        { label: "Service", value: "Haircut", valueClass: "text-[#2563EB]", extra: "₹800" },
                        { label: "Customer", value: "Anjali Singh" },
                        { label: "Staff", value: "Priya Sharma" },
                        { label: "Date & Time", value: "Tomorrow, 9:00 AM" },
                        { label: "Branch", value: "Banjara Hills" },
                        { label: "Duration", value: "45 minutes" },
                      ].map((row) => (
                        <div key={row.label} className="flex justify-between items-center">
                          <span className="text-sm text-gray-400">{row.label}</span>
                          <div className="flex items-center gap-2">
                            <span className={`font-medium text-white ${row.valueClass ?? ""}`}>
                              {row.value}
                            </span>
                            {row.extra && (
                              <span className="text-sm font-semibold text-[#2563EB]">{row.extra}</span>
                            )}
                          </div>
                        </div>
                      ))}
                    </div>

                    {/* Channel selector */}
                    <p className="text-sm text-gray-400 mt-4 mb-2">Booking Channel</p>
                    <div className="grid grid-cols-4 gap-2">
                      {BOOKING_CHANNELS.map(({ id, label, Icon }) => (
                        <button
                          key={id}
                          onClick={() => setSelectedChannel(id)}
                          className={`bg-[#1C1F2A] rounded-xl p-3 text-center cursor-pointer border transition-colors ${
                            selectedChannel === id
                              ? "border-[#2563EB] bg-[#2563EB]/10 text-[#2563EB]"
                              : "border-white/5 text-gray-400 hover:text-white"
                          }`}
                        >
                          <Icon className="w-5 h-5 mx-auto mb-1" />
                          <p className="text-xs">{label}</p>
                        </button>
                      ))}
                    </div>

                    {/* WhatsApp toggle */}
                    <div className="flex items-center justify-between mt-4 bg-[#1C1F2A] rounded-xl px-4 py-3">
                      <div className="flex items-center gap-2">
                        <MessageCircle className="w-5 h-5 text-[#25D366]" />
                        <span className="text-sm text-white">Send WhatsApp confirmation</span>
                      </div>
                      <button
                        onClick={() => setWaToggle((v) => !v)}
                        className={`relative w-11 h-6 rounded-full transition-colors ${
                          waToggle ? "bg-[#25D366]" : "bg-white/10"
                        }`}
                      >
                        <span
                          className={`absolute top-0.5 w-5 h-5 bg-white rounded-full shadow transition-transform ${
                            waToggle ? "translate-x-5" : "translate-x-0.5"
                          }`}
                        />
                      </button>
                    </div>
                  </div>
                )}
              </motion.div>
            </AnimatePresence>

            {/* Navigation */}
            <div className="flex justify-between mt-6">
              {step > 1 ? (
                <button
                  onClick={() => setStep((s) => s - 1)}
                  className="border border-white/10 text-white px-4 py-2 rounded-lg text-sm hover:border-white/30 transition-colors"
                >
                  Back
                </button>
              ) : (
                <div />
              )}

              {step < 4 ? (
                <button
                  onClick={() => setStep((s) => s + 1)}
                  className="bg-[#2563EB] text-white px-6 py-2 rounded-lg text-sm font-semibold hover:bg-[#2563EB]/90 transition-colors"
                >
                  Next →
                </button>
              ) : (
                <button
                  onClick={handleClose}
                  className="flex items-center gap-2 text-white font-semibold px-6 py-3 rounded-xl text-sm"
                  style={{
                    background: "#2563EB",
                    boxShadow: "0 0 20px rgba(37,99,235,0.4)",
                  }}
                >
                  <Check className="w-4 h-4" />
                  Confirm Booking
                </button>
              )}
            </div>
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  )
}

"use client"

import { useState, useEffect } from "react"
import { motion, AnimatePresence } from "framer-motion"
import {
  Calendar,
  ChevronDown,
  Users,
  Tag,
  Search,
  Bell,
  Plus,
  X,
  Clock,
  User,
  CalendarDays,
  Phone,
  MessageCircle,
  Globe,
  FileText,
  RefreshCw,
  Trash2,
  Check,
  Star,
} from "lucide-react"

// Types
interface Staff {
  id: string
  name: string
  role: string
  avatar: string
  available: boolean
}

interface Appointment {
  id: string
  staffId: string
  service: string
  customer: string
  phone: string
  startTime: string
  endTime: string
  price: number
  category: "hair" | "color" | "nails" | "spa"
  status: "confirmed" | "in-progress" | "pending"
  bookedVia: "whatsapp" | "web" | "phone"
  notes?: string
}

// Category colors
const categoryColors: Record<string, string> = {
  hair: "#2563EB",
  color: "#A855F7",
  nails: "#D946EF",
  spa: "#10B981",
}

const EMPTY_STAFF: Staff[] = []
const EMPTY_APPOINTMENTS: Appointment[] = []

const timeSlots = [
  "08:00", "09:00", "10:00", "11:00", "12:00",
  "13:00", "14:00", "15:00", "16:00", "17:00",
  "18:00", "19:00", "20:00", "21:00",
]

// Helper to calculate appointment position
function getAppointmentPosition(startTime: string, endTime: string) {
  const [startHour, startMin] = startTime.split(":").map(Number)
  const [endHour, endMin] = endTime.split(":").map(Number)

  const startOffset = (startHour - 8) * 80 + (startMin / 60) * 80
  const duration = (endHour - startHour) * 80 + ((endMin - startMin) / 60) * 80

  return { top: startOffset, height: Math.max(duration, 40) }
}

// Helper to format time
function formatTime(time: string) {
  const [hour, min] = time.split(":").map(Number)
  const ampm = hour >= 12 ? "PM" : "AM"
  const h = hour % 12 || 12
  return `${h}:${min.toString().padStart(2, "0")} ${ampm}`
}

function formatTimeFromDate(date: Date) {
  return date.toLocaleTimeString("en-IN", { hour: "2-digit", minute: "2-digit", hour12: true })
}

export function BookingCalendar() {
  const [selectedAppointment, setSelectedAppointment] = useState<Appointment | null>(null)
  const [drawerOpen, setDrawerOpen] = useState(false)
  const [viewMode, setViewMode] = useState<"Day" | "Week" | "Month">("Week")
  const [hoveredSlot, setHoveredSlot] = useState<{ staffId: string; hour: number } | null>(null)
  const [modalOpen, setModalOpen] = useState(false)
  const [staffMembers, setStaffMembers] = useState<Staff[]>(EMPTY_STAFF)
  const [appointments, setAppointments] = useState<Appointment[]>(EMPTY_APPOINTMENTS)
  const [branchId, setBranchId] = useState<string | null>(null)
  const [services, setServices] = useState<any[]>([])
  const [customers, setCustomers] = useState<any[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [calendarDate] = useState(new Date())

  useEffect(() => {
    let active = true

    const fetchSeed = async () => {
      try {
        setLoading(true)
        setError(null)
        const [branchesRes, servicesRes, customersRes] = await Promise.all([
          fetch('/api/branches'),
          fetch('/api/services'),
          fetch('/api/customers'),
        ])

        if (!branchesRes.ok || !servicesRes.ok || !customersRes.ok) {
          throw new Error('Failed to load booking data')
        }

        const branchesPayload = await branchesRes.json()
        const servicesPayload = await servicesRes.json()
        const customersPayload = await customersRes.json()

        if (!active) return

        const firstBranch = branchesPayload.data?.[0]
        setBranchId(firstBranch?._id ?? null)
        setServices(servicesPayload.data ?? [])
        setCustomers(customersPayload.data ?? [])
      } catch (err) {
        if (active) {
          setError(err instanceof Error ? err.message : 'Failed to load booking data')
        }
      } finally {
        if (active) {
          setLoading(false)
        }
      }
    }

    fetchSeed()
    return () => {
      active = false
    }
  }, [])

  useEffect(() => {
    let active = true

    const fetchStaffAndAppointments = async () => {
      if (!branchId) return
      try {
        setLoading(true)
        setError(null)
        const [staffRes, apptsRes] = await Promise.all([
          fetch(`/api/users?branchId=${branchId}`),
          fetch(`/api/appointments?branchId=${branchId}&date=${calendarDate.toISOString()}`),
        ])

        if (!staffRes.ok || !apptsRes.ok) {
          throw new Error('Failed to load calendar data')
        }

        const staffPayload = await staffRes.json()
        const apptsPayload = await apptsRes.json()

        if (!active) return

        const normalizedStaff = (staffPayload.data ?? []).map((staff: any) => ({
          id: staff._id,
          name: staff.name,
          role: staff.role,
          avatar: '',
          available: staff.isActive,
        }))

        const normalizedAppts = (apptsPayload.data ?? []).map((appt: any) => {
          const slot = new Date(appt.slot)
          const duration = appt.duration ?? appt.serviceId?.duration ?? 30
          const end = new Date(slot.getTime() + duration * 60000)

          return {
            id: appt._id,
            staffId: appt.staffId?._id ?? appt.staffId,
            service: appt.serviceId?.name ?? 'Service',
            customer: appt.customerId?.name ?? 'Customer',
            phone: appt.customerId?.phone ?? '',
            startTime: slot.toTimeString().slice(0, 5),
            endTime: end.toTimeString().slice(0, 5),
            price: appt.price ?? 0,
            category: (appt.serviceId?.category ?? 'hair') as Appointment['category'],
            status: appt.status ?? 'pending',
            bookedVia: appt.channel === 'call' ? 'phone' : appt.channel,
            notes: appt.notes,
          }
        })

        setStaffMembers(normalizedStaff)
        setAppointments(normalizedAppts)
      } catch (err) {
        if (active) {
          setError(err instanceof Error ? err.message : 'Failed to load calendar data')
        }
      } finally {
        if (active) {
          setLoading(false)
        }
      }
    }

    fetchStaffAndAppointments()
    return () => {
      active = false
    }
  }, [branchId, calendarDate])

  const openDrawer = (appointment: Appointment) => {
    setSelectedAppointment(appointment)
    setDrawerOpen(true)
  }

  const closeDrawer = () => {
    setDrawerOpen(false)
    setTimeout(() => setSelectedAppointment(null), 300)
  }

  const getStaffAppointments = (staffId: string) => {
    return appointments.filter((apt) => apt.staffId === staffId)
  }

  return (
    <div className="h-screen flex flex-col bg-[#0A0B0F] text-white overflow-hidden">
      {/* Top Bar */}
      <header className="h-16 border-b border-white/5 bg-[#0A0B0F]/80 backdrop-blur-md flex justify-between items-center px-6 flex-shrink-0">
        <h2 className="text-xl font-semibold text-[#B4C5FF]">Booking Calendar</h2>
        <div className="flex items-center gap-4">
          <button className="w-10 h-10 rounded-full flex items-center justify-center text-gray-400 hover:text-[#2563EB] hover:bg-white/5 transition-colors">
            <Search className="w-5 h-5" />
          </button>
          <button className="w-10 h-10 rounded-full flex items-center justify-center text-gray-400 hover:text-[#2563EB] hover:bg-white/5 transition-colors relative">
            <Bell className="w-5 h-5" />
            <span className="absolute top-2 right-2 w-2 h-2 bg-red-500 rounded-full" />
          </button>
          <div className="h-6 w-px bg-white/10 mx-2" />
          <div className="w-8 h-8 rounded-full bg-[#16181F] border border-white/10 overflow-hidden">
            <img
              src="https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=100&h=100&fit=crop&crop=face"
              alt="User"
              className="w-full h-full object-cover"
            />
          </div>
        </div>
      </header>

      {/* Filter Bar */}
      <div className="flex items-center justify-between bg-[#0D0E14] p-4 border-b border-white/5 flex-shrink-0">
        <div className="flex items-center gap-3">
          {/* Date Picker */}
          <button className="flex items-center gap-2 px-4 py-2 bg-[#16181F] rounded-lg border border-white/5 text-sm text-white hover:border-[#2563EB]/50 transition-colors">
            <Calendar className="w-4 h-4 text-[#2563EB]" />
            {calendarDate.toLocaleDateString("en-IN", { day: "2-digit", month: "short", year: "numeric" })}
            <ChevronDown className="w-4 h-4 text-gray-400 ml-1" />
          </button>

          <div className="h-6 w-px bg-white/10 mx-1" />

          {/* Staff Filter */}
          <button className="flex items-center gap-2 px-3 py-1.5 rounded-full border border-white/10 text-xs font-medium text-white hover:bg-white/5 transition-colors">
            <Users className="w-4 h-4" />
            All Staff
          </button>

          {/* Category Filter */}
          <button className="flex items-center gap-2 px-3 py-1.5 rounded-full border border-white/10 text-xs font-medium text-white hover:bg-white/5 transition-colors">
            <Tag className="w-4 h-4" />
            Category
          </button>
        </div>

        {/* View Toggle */}
        <div className="flex items-center bg-[#0A0B0F] p-1 rounded-lg border border-white/5">
          {(["Day", "Week", "Month"] as const).map((mode) => (
            <button
