      {/* Calendar Grid */}
      <div className="flex-1 overflow-hidden flex flex-col bg-[#0D0E14] m-4 rounded-xl border border-white/5">
        {/* Staff Headers */}
        <div className="flex border-b border-white/5 bg-[#0A0B0F] flex-shrink-0">
