              {/* Staff Columns */}
              {staffMembers.map((staff) => (
                <div key={staff.id} className="relative p-1">
                  {staff.available ? (
                    <>
                      {/* Empty slot hover areas */}
                      {timeSlots.map((_, hourIndex) => (
                        <div
