const EMPTY_SLOTS: { time: string; available: boolean; raw: string }[] = []

const BOOKING_CHANNELS = [
  { id: "web", label: "Web", Icon: Globe },
  { id: "whatsapp", label: "WhatsApp", Icon: MessageCircle },
  { id: "walkin", label: "Walk-in", Icon: User },
  { id: "call", label: "Call", Icon: Phone },
]

const SERVICE_CATEGORIES = ["All", "Hair", "Skin", "Nails", "Spa", "Packages"]

function generateDateChips() {
  const chips = []
  const today = new Date()
  const days = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"]
  for (let i = 0; i < 14; i++) {
    const d = new Date(today)
    d.setDate(today.getDate() + i)
    chips.push({
      label: `${days[d.getDay()]} ${d.getDate()}`,
      isToday: i === 0,
    })
  }
  return chips
}

interface NewBookingModalProps {
  open: boolean
  onClose: () => void
  services: any[]
  staff: Staff[]
  customers: any[]
  branchId: string | null
}

export function NewBookingModal({ open, onClose, services, staff, customers, branchId }: NewBookingModalProps) {
  const [step, setStep] = useState(1)
  const [selectedService, setSelectedService] = useState<string | null>(null)
  const [selectedCategory, setSelectedCategory] = useState("All")
  const [selectedStaff, setSelectedStaff] = useState(0)
  const [selectedDate, setSelectedDate] = useState(0)
  const [selectedSlot, setSelectedSlot] = useState<string | null>(null)
  const [selectedChannel, setSelectedChannel] = useState("whatsapp")
  const [waToggle, setWaToggle] = useState(true)
  const [selectedCustomer, setSelectedCustomer] = useState(0)
  const [slots, setSlots] = useState(EMPTY_SLOTS)
  const [slotsLoading, setSlotsLoading] = useState(false)
  const [slotsError, setSlotsError] = useState<string | null>(null)

  const dateChips = generateDateChips()
  const selectedServiceData = services.find((svc) => svc._id === selectedService)
  const selectedStaffData = staff[selectedStaff]
  const selectedCustomerData = customers[selectedCustomer]
  const selectedDateValue = (() => {
    const today = new Date()
    const date = new Date(today)
    date.setDate(today.getDate() + selectedDate)
    return date
  })()

  useEffect(() => {
    let active = true

    const fetchSlots = async () => {
      if (!branchId || !selectedService || !selectedStaffData) {
        setSlots([])
        return
      }

      try {
        setSlotsLoading(true)
        setSlotsError(null)
        const res = await fetch(
          `/api/appointments/slots?branchId=${branchId}&staffId=${selectedStaffData.id}&serviceId=${selectedService}&date=${selectedDateValue.toISOString()}`
        )

        if (!res.ok) {
          throw new Error('Failed to load slots')
        }

        const payload = await res.json()
        if (!active) return

        const normalized = (payload.data ?? []).map((slot: any) => {
          const time = new Date(slot.time)
          return {
            raw: slot.time,
            time: time.toLocaleTimeString('en-IN', { hour: 'numeric', minute: '2-digit' }),
            available: slot.available,
          }
        })

        setSlots(normalized)
      } catch (err) {
        if (active) {
          setSlotsError(err instanceof Error ? err.message : 'Failed to load slots')
        }
      } finally {
        if (active) {
          setSlotsLoading(false)
        }
      }
    }

    fetchSlots()
    return () => {
      active = false
    }
  }, [branchId, selectedService, selectedStaffData, selectedDateValue])

  const slotGroups = [
    {
      label: "Morning",
      slots: slots.filter((slot) => {
        const hour = new Date(slot.raw).getHours()
        return hour < 12
      }),
    },
    {
      label: "Afternoon",
      slots: slots.filter((slot) => {
        const hour = new Date(slot.raw).getHours()
        return hour >= 12 && hour < 17
      }),
    },
    {
      label: "Evening",
      slots: slots.filter((slot) => new Date(slot.raw).getHours() >= 17),
    },
  ]

  const handleClose = () => {
    onClose()
    // Reset after close animation
    setTimeout(() => {
      setStep(1)
      setSelectedService(null)
      setSelectedCategory("All")
      setSelectedStaff(0)
      setSelectedDate(0)
      setSelectedSlot(null)
      setSelectedChannel("whatsapp")
      setWaToggle(true)
      setSelectedCustomer(0)
      setSlots(EMPTY_SLOTS)
      setSlotsError(null)
    }, 300)
  }

  const serviceCategories = [
    "All",
    ...Array.from(
      new Set(services.map((svc) => svc.category?.charAt(0).toUpperCase() + svc.category?.slice(1)))
    ),
  ]
  const filteredServices = selectedCategory === "All"
    ? services
    : services.filter(
