// Types
interface Staff {
  id: string
  name: string
  role: string
  avatar: string
  available: boolean
}

interface Appointment {
  id: string
  staffId: string
  service: string
  customer: string
  phone: string
  startTime: string
  endTime: string
  price: number
  category: "hair" | "color" | "nails" | "spa"
  status: "confirmed" | "in-progress" | "pending"
  bookedVia: "whatsapp" | "web" | "phone"
  notes?: string
}

// Category colors
