// Types
interface Staff {
  id: string
  name: string
  role: string
  avatar: string
  available: boolean
}

interface Appointment {
  id: string
  staffId: string
  service: string
  customer: string
  phone: string
  startTime: string
  endTime: string
  price: number
  category: "hair" | "skin" | "nails" | "spa" | "packages" | "bridal" | "color"
  status: "confirmed" | "in-progress" | "pending"
  bookedVia: "whatsapp" | "web" | "phone"
  notes?: string
}

// Category colors
const categoryColors: Record<string, string> = {
  hair: "#2563EB",
  color: "#A855F7",
  nails: "#D946EF",
  spa: "#10B981",
}

const EMPTY_STAFF: Staff[] = []
const EMPTY_APPOINTMENTS: Appointment[] = []

const timeSlots = [
  "08:00", "09:00", "10:00", "11:00", "12:00",
  "13:00", "14:00", "15:00", "16:00", "17:00",
  "18:00", "19:00", "20:00", "21:00",
]

// Helper to calculate appointment position
function getAppointmentPosition(startTime: string, endTime: string) {
  const [startHour, startMin] = startTime.split(":").map(Number)
  const [endHour, endMin] = endTime.split(":").map(Number)

  const startOffset = (startHour - 8) * 80 + (startMin / 60) * 80
  const duration = (endHour - startHour) * 80 + ((endMin - startMin) / 60) * 80

  return { top: startOffset, height: Math.max(duration, 40) }
}

// Helper to format time
function formatTime(time: string) {
  const [hour, min] = time.split(":").map(Number)
  const ampm = hour >= 12 ? "PM" : "AM"
  const h = hour % 12 || 12
  return `${h}:${min.toString().padStart(2, "0")} ${ampm}`
}

function formatTimeFromDate(date: Date) {
  return date.toLocaleTimeString("en-IN", { hour: "2-digit", minute: "2-digit", hour12: true })
}

export function BookingCalendar() {
  const [selectedAppointment, setSelectedAppointment] = useState<Appointment | null>(null)
  const [drawerOpen, setDrawerOpen] = useState(false)
  const [viewMode, setViewMode] = useState<"Day" | "Week" | "Month">("Week")
  const [hoveredSlot, setHoveredSlot] = useState<{ staffId: string; hour: number } | null>(null)
  const [modalOpen, setModalOpen] = useState(false)
  const [staffMembers, setStaffMembers] = useState<Staff[]>(EMPTY_STAFF)
  const [appointments, setAppointments] = useState<Appointment[]>(EMPTY_APPOINTMENTS)
  const [branchId, setBranchId] = useState<string | null>(null)
  const [services, setServices] = useState<any[]>([])
  const [customers, setCustomers] = useState<any[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [calendarDate] = useState(new Date())

  useEffect(() => {
    let active = true

    const fetchSeed = async () => {
      try {
        setLoading(true)
        setError(null)
        const [branchesRes, servicesRes, customersRes] = await Promise.all([
          fetch('/api/branches'),
          fetch('/api/services'),
          fetch('/api/customers'),
        ])

        if (!branchesRes.ok || !servicesRes.ok || !customersRes.ok) {
          throw new Error('Failed to load booking data')
        }

        const branchesPayload = await branchesRes.json()
        const servicesPayload = await servicesRes.json()
        const customersPayload = await customersRes.json()

        if (!active) return

        const firstBranch = branchesPayload.data?.[0]
        setBranchId(firstBranch?._id ?? null)
        setServices(servicesPayload.data ?? [])
        setCustomers(customersPayload.data ?? [])
      } catch (err) {
        if (active) {
          setError(err instanceof Error ? err.message : 'Failed to load booking data')
        }
      } finally {
        if (active) {
          setLoading(false)
        }
      }
    }

    fetchSeed()
    return () => {
      active = false
    }
  }, [])

  useEffect(() => {
    let active = true

    const fetchStaffAndAppointments = async () => {
      if (!branchId) return
      try {
        setLoading(true)
        setError(null)
        const [staffRes, apptsRes] = await Promise.all([
          fetch(`/api/users?branchId=${branchId}`),
          fetch(`/api/appointments?branchId=${branchId}&date=${calendarDate.toISOString()}`),
        ])

        if (!staffRes.ok || !apptsRes.ok) {
          throw new Error('Failed to load calendar data')
        }

        const staffPayload = await staffRes.json()
        const apptsPayload = await apptsRes.json()

        if (!active) return

        const normalizedStaff = (staffPayload.data ?? []).map((staff: any) => ({
          id: staff._id,
          name: staff.name,
          role: staff.role,
          avatar: '',
          available: staff.isActive,
        }))

        const normalizedAppts = (apptsPayload.data ?? []).map((appt: any) => {
          const slot = new Date(appt.slot)
          const duration = appt.duration ?? appt.serviceId?.duration ?? 30
          const end = new Date(slot.getTime() + duration * 60000)

          return {
            id: appt._id,
            staffId: appt.staffId?._id ?? appt.staffId,
            service: appt.serviceId?.name ?? 'Service',
            customer: appt.customerId?.name ?? 'Customer',
            phone: appt.customerId?.phone ?? '',
            startTime: slot.toTimeString().slice(0, 5),
            endTime: end.toTimeString().slice(0, 5),
            price: appt.price ?? 0,
            category: (appt.serviceId?.category ?? 'hair') as Appointment['category'],
            status: appt.status ?? 'pending',
            bookedVia: appt.channel === 'call' ? 'phone' : appt.channel,
            notes: appt.notes,
          }
        })

        setStaffMembers(normalizedStaff)
        setAppointments(normalizedAppts)
      } catch (err) {
        if (active) {
          setError(err instanceof Error ? err.message : 'Failed to load calendar data')
        }
      } finally {
        if (active) {
          setLoading(false)
        }
      }
    }

    fetchStaffAndAppointments()
    return () => {
      active = false
    }
  }, [branchId, calendarDate])

  const openDrawer = (appointment: Appointment) => {
    setSelectedAppointment(appointment)
    setDrawerOpen(true)
  }

  const closeDrawer = () => {
    setDrawerOpen(false)
    setTimeout(() => setSelectedAppointment(null), 300)
  }

  const getStaffAppointments = (staffId: string) => {
    return appointments.filter((apt) => apt.staffId === staffId)
  }

  return (
    <div className="h-screen flex flex-col bg-[#0A0B0F] text-white overflow-hidden">
      {/* Top Bar */}
      <header className="h-16 border-b border-white/5 bg-[#0A0B0F]/80 backdrop-blur-md flex justify-between items-center px-6 flex-shrink-0">
        <h2 className="text-xl font-semibold text-[#B4C5FF]">Booking Calendar</h2>
        <div className="flex items-center gap-4">
          <button className="w-10 h-10 rounded-full flex items-center justify-center text-gray-400 hover:text-[#2563EB] hover:bg-white/5 transition-colors">
            <Search className="w-5 h-5" />
          </button>
          <button className="w-10 h-10 rounded-full flex items-center justify-center text-gray-400 hover:text-[#2563EB] hover:bg-white/5 transition-colors relative">
            <Bell className="w-5 h-5" />
            <span className="absolute top-2 right-2 w-2 h-2 bg-red-500 rounded-full" />
          </button>
          <div className="h-6 w-px bg-white/10 mx-2" />
          <div className="w-8 h-8 rounded-full bg-[#16181F] border border-white/10 overflow-hidden">
            <img
              src="https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=100&h=100&fit=crop&crop=face"
              alt="User"
              className="w-full h-full object-cover"
            />
          </div>
        </div>
      </header>

      {/* Filter Bar */}
      <div className="flex items-center justify-between bg-[#0D0E14] p-4 border-b border-white/5 flex-shrink-0">
        <div className="flex items-center gap-3">
          {/* Date Picker */}
          <button className="flex items-center gap-2 px-4 py-2 bg-[#16181F] rounded-lg border border-white/5 text-sm text-white hover:border-[#2563EB]/50 transition-colors">
            <Calendar className="w-4 h-4 text-[#2563EB]" />
            {calendarDate.toLocaleDateString("en-IN", { day: "2-digit", month: "short", year: "numeric" })}
            <ChevronDown className="w-4 h-4 text-gray-400 ml-1" />
          </button>

          <div className="h-6 w-px bg-white/10 mx-1" />

          {/* Staff Filter */}
          <button className="flex items-center gap-2 px-3 py-1.5 rounded-full border border-white/10 text-xs font-medium text-white hover:bg-white/5 transition-colors">
            <Users className="w-4 h-4" />
            All Staff
          </button>

          {/* Category Filter */}
          <button className="flex items-center gap-2 px-3 py-1.5 rounded-full border border-white/10 text-xs font-medium text-white hover:bg-white/5 transition-colors">
            <Tag className="w-4 h-4" />
            Category
          </button>
        </div>

        {/* View Toggle */}
        <div className="flex items-center bg-[#0A0B0F] p-1 rounded-lg border border-white/5">
          {(["Day", "Week", "Month"] as const).map((mode) => (
            <button
              key={mode}
              onClick={() => setViewMode(mode)}
              className={`px-4 py-1.5 rounded-md text-xs font-medium transition-colors ${
                viewMode === mode
                  ? "bg-[#16181F] text-[#2563EB] shadow-sm"
                  : "text-gray-400 hover:text-white"
              }`}
            >
              {mode}
            </button>
          ))}
        </div>
      </div>

      {error && (
        <div className="mx-4 mt-2 rounded-xl border border-red-500/20 bg-red-500/10 px-4 py-2 text-xs text-red-300">
          {error}
