              >
                {staff.available ? (
                  staff.avatar ? (
                    <img
                      src={staff.avatar}
                      alt={staff.name}
                      className="w-8 h-8 rounded-full border border-white/10 object-cover"
                    />
                  ) : (
                    <div className="w-8 h-8 rounded-full bg-[#16181F] flex items-center justify-center">
                      <span className="text-[10px] text-gray-400">
                        {staff.name
                          .split(' ')
                          .map((part) => part[0])
                          .join('')
                          .slice(0, 2)}
                      </span>
                    </div>
                  )
                ) : (
                  <div className="w-8 h-8 rounded-full bg-[#16181F] flex items-center justify-center">
