                  ) : (
                    <div className="absolute inset-0 bg-[#16181F]/30 flex items-center justify-center">
                      <p className="text-xs text-gray-500 -rotate-90 tracking-widest uppercase">
                        Unavailable
                      </p>
                    </div>
                  )}
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>

      {/* Floating Action Button */}
