                <button className="flex-1 py-2.5 rounded-lg border border-red-500/30 text-red-400 font-medium text-sm hover:bg-red-500/10 transition-colors flex items-center justify-center gap-2">
                  <Trash2 className="w-4 h-4" />
                  Cancel
                </button>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* New Booking Modal */}
      <NewBookingModal
        open={modalOpen}
        onClose={() => setModalOpen(false)}
        services={services}
        staff={staffMembers}
        customers={customers}
        branchId={branchId}
      />

      {/* Custom scrollbar styles */}
      <style jsx global>{`
        .calendar-scroll::-webkit-scrollbar {
          width: 8px;
          height: 8px;
        }
        .calendar-scroll::-webkit-scrollbar-track {
          background: transparent;
        }
        .calendar-scroll::-webkit-scrollbar-thumb {
          background-color: rgba(255, 255, 255, 0.1);
          border-radius: 4px;
        }
        .calendar-scroll::-webkit-scrollbar-thumb:hover {
          background-color: rgba(255, 255, 255, 0.2);
        }
      `}</style>
    </div>
  )
}

// ─── NewBookingModal ────────────────────────────────────────────────────────

const EMPTY_SLOTS: { time: string; available: boolean; raw: string }[] = []

const BOOKING_CHANNELS = [
  { id: "web", label: "Web", Icon: Globe },
  { id: "whatsapp", label: "WhatsApp", Icon: MessageCircle },
  { id: "walkin", label: "Walk-in", Icon: User },
  { id: "call", label: "Call", Icon: Phone },
]

function generateDateChips() {
  const chips = []
  const today = new Date()
  const days = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"]
  for (let i = 0; i < 14; i++) {
    const d = new Date(today)
    d.setDate(today.getDate() + i)
    chips.push({
      label: `${days[d.getDay()]} ${d.getDate()}`,
      isToday: i === 0,
    })
  }
  return chips
}

interface NewBookingModalProps {
  open: boolean
  onClose: () => void
  services: any[]
  staff: Staff[]
  customers: any[]
  branchId: string | null
}

export function NewBookingModal({ open, onClose, services, staff, customers, branchId }: NewBookingModalProps) {
  const [step, setStep] = useState(1)
  const [selectedService, setSelectedService] = useState<string | null>(null)
  const [selectedCategory, setSelectedCategory] = useState("All")
  const [selectedStaff, setSelectedStaff] = useState(0)
  const [selectedDate, setSelectedDate] = useState(0)
  const [selectedSlot, setSelectedSlot] = useState<string | null>(null)
  const [selectedChannel, setSelectedChannel] = useState("whatsapp")
  const [waToggle, setWaToggle] = useState(true)
  const [selectedCustomer, setSelectedCustomer] = useState(0)
  const [slots, setSlots] = useState(EMPTY_SLOTS)
  const [slotsLoading, setSlotsLoading] = useState(false)
  const [slotsError, setSlotsError] = useState<string | null>(null)

  const dateChips = generateDateChips()
  const selectedServiceData = services.find((svc) => svc._id === selectedService)
  const selectedStaffData = staff[selectedStaff]
  const selectedCustomerData = customers[selectedCustomer]
  const selectedDateValue = (() => {
    const today = new Date()
    const date = new Date(today)
    date.setDate(today.getDate() + selectedDate)
    return date
  })()

  useEffect(() => {
    let active = true

    const fetchSlots = async () => {
      if (!branchId || !selectedService || !selectedStaffData) {
        setSlots([])
        return
      }

      try {
        setSlotsLoading(true)
        setSlotsError(null)
        const res = await fetch(
          `/api/appointments/slots?branchId=${branchId}&staffId=${selectedStaffData.id}&serviceId=${selectedService}&date=${selectedDateValue.toISOString()}`
        )

        if (!res.ok) {
          throw new Error('Failed to load slots')
        }

        const payload = await res.json()
        if (!active) return

        const normalized = (payload.data ?? []).map((slot: any) => {
          const time = new Date(slot.time)
          return {
            raw: slot.time,
            time: time.toLocaleTimeString('en-IN', { hour: 'numeric', minute: '2-digit' }),
            available: slot.available,
          }
        })

        setSlots(normalized)
      } catch (err) {
        if (active) {
          setSlotsError(err instanceof Error ? err.message : 'Failed to load slots')
        }
      } finally {
        if (active) {
          setSlotsLoading(false)
        }
      }
    }

    fetchSlots()
    return () => {
      active = false
    }
  }, [branchId, selectedService, selectedStaffData, selectedDateValue])

  const slotGroups = [
    {
      label: "Morning",
      slots: slots.filter((slot) => {
        const hour = new Date(slot.raw).getHours()
        return hour < 12
      }),
    },
    {
      label: "Afternoon",
      slots: slots.filter((slot) => {
        const hour = new Date(slot.raw).getHours()
        return hour >= 12 && hour < 17
      }),
    },
    {
      label: "Evening",
      slots: slots.filter((slot) => new Date(slot.raw).getHours() >= 17),
    },
  ]

  const handleClose = () => {
    onClose()
    // Reset after close animation
    setTimeout(() => {
      setStep(1)
      setSelectedService(null)
      setSelectedCategory("All")
      setSelectedStaff(0)
      setSelectedDate(0)
      setSelectedSlot(null)
      setSelectedChannel("whatsapp")
      setWaToggle(true)
      setSelectedCustomer(0)
      setSlots(EMPTY_SLOTS)
      setSlotsError(null)
    }, 300)
  }

  const serviceCategories = [
    "All",
    ...Array.from(
      new Set(services.map((svc) => svc.category?.charAt(0).toUpperCase() + svc.category?.slice(1)))
    ),
  ]
  const filteredServices = selectedCategory === "All"
    ? services
    : services.filter(
        (svc) => (svc.category?.charAt(0).toUpperCase() + svc.category?.slice(1)) === selectedCategory
      )

  const STEP_LABELS = ["Customer", "Service", "Schedule", "Confirm"]

  function StepSlot({ s }: { s: { time: string; available: boolean } }) {
    const active = selectedSlot === s.time
    if (!s.available) {
      return (
        <span className="bg-[#1C1F2A] text-gray-600 text-xs px-3 py-1.5 rounded-lg cursor-not-allowed line-through">
          {s.time}
        </span>
      )
    }
    return (
      <button
        onClick={() => setSelectedSlot(s.time)}
        className={`text-xs px-3 py-1.5 rounded-lg transition-colors ${
          active
            ? "bg-[#2563EB] text-white border border-[#2563EB]"
            : "bg-[#2563EB]/15 border border-[#2563EB]/40 text-[#2563EB] hover:bg-[#2563EB]/25"
        }`}
      >
        {s.time}
      </button>
    )
  }

  return (
    <AnimatePresence>
      {open && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          className="fixed inset-0 z-50 flex items-start justify-center backdrop-blur-xl bg-black/60 overflow-y-auto"
          onClick={(e) => e.target === e.currentTarget && handleClose()}
        >
          <motion.div
            initial={{ opacity: 0, y: 30, scale: 0.97 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 20, scale: 0.97 }}
            transition={{ type: "spring", damping: 28, stiffness: 300 }}
            className="relative w-full max-w-2xl mx-auto mt-12 mb-12 bg-[#16181F] rounded-2xl p-8 border border-white/5"
            style={{ boxShadow: "0 0 60px #2563EB15" }}
          >
            {/* Close */}
            <button
              onClick={handleClose}
              className="absolute top-4 right-4 w-8 h-8 rounded-full bg-white/5 flex items-center justify-center text-gray-400 hover:text-white transition-colors"
            >
              <X className="w-4 h-4" />
            </button>

            {/* Step Indicator */}
            <div className="flex items-center mb-8">
              {STEP_LABELS.map((label, i) => {
                const num = i + 1
                const isCompleted = step > num
                const isActive = step === num
                return (
                  <div key={label} className="flex items-center flex-1 last:flex-none">
                    <div className="flex flex-col items-center gap-1">
                      <div
                        className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-semibold transition-colors ${
                          isCompleted
                            ? "bg-[#2563EB] text-white"
                            : isActive
                            ? "bg-[#2563EB] text-white"
                            : "bg-[#1C1F2A] border border-white/10 text-gray-500"
                        }`}
                      >
                        {isCompleted ? <Check className="w-4 h-4" /> : num}
                      </div>
                      <span
                        className={`text-[10px] font-medium ${
                          isActive ? "text-white" : "text-gray-500"
