                        <div key={label}>
                          <p className="text-xs text-gray-500 mb-2">{label}</p>
                          <div className="flex flex-wrap gap-2">
                            {slotsLoading && slots.length === 0 ? (
                              <div className="h-6 w-32 rounded-md bg-white/5 animate-pulse" />
                            ) : (
                              slots.map((s) => <StepSlot key={s.time} s={s} />)
                            )}
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {/* STEP 4 — Confirm */}
                {step === 4 && (
                  <div>
                    <h3 className="text-lg font-semibold text-white mb-4">Confirm Booking</h3>

                    {/* Summary */}
                    <div className="bg-[#0A0B0F] rounded-xl p-5 space-y-3">
                      {[
                        {
                          label: "Service",
                          value: selectedServiceData?.name ?? "",
                          valueClass: "text-[#2563EB]",
                          extra: selectedServiceData ? `₹${selectedServiceData.price}` : undefined,
                        },
                        { label: "Customer", value: selectedCustomerData?.name ?? "" },
                        { label: "Staff", value: selectedStaffData?.name ?? "" },
                        {
                          label: "Date & Time",
                          value: selectedSlot
                            ? `${selectedDateValue.toLocaleDateString("en-IN", { day: "numeric", month: "short" })}, ${selectedSlot}`
                            : "",
                        },
                        { label: "Branch", value: branchId ? "Selected branch" : "" },
                        { label: "Duration", value: selectedServiceData ? `${selectedServiceData.duration} minutes` : "" },
                      ].filter((row) => row.value).map((row) => (
                        <div key={row.label} className="flex justify-between items-center">
                          <span className="text-sm text-gray-400">{row.label}</span>
                          <div className="flex items-center gap-2">
                            <span className={`font-medium text-white ${row.valueClass ?? ""}`}>
                              {row.value}
                            </span>
                            {row.extra && (
                              <span className="text-sm font-semibold text-[#2563EB]">{row.extra}</span>
                            )}
                          </div>
                        </div>
                      ))}
                    </div>

                    {/* Channel selector */}
                    <p className="text-sm text-gray-400 mt-4 mb-2">Booking Channel</p>
                    <div className="grid grid-cols-4 gap-2">
                      {BOOKING_CHANNELS.map(({ id, label, Icon }) => (
                        <button
                          key={id}
                          onClick={() => setSelectedChannel(id)}
                          className={`bg-[#1C1F2A] rounded-xl p-3 text-center cursor-pointer border transition-colors ${
                            selectedChannel === id
                              ? "border-[#2563EB] bg-[#2563EB]/10 text-[#2563EB]"
                              : "border-white/5 text-gray-400 hover:text-white"
                          }`}
                        >
                          <Icon className="w-5 h-5 mx-auto mb-1" />
                          <p className="text-xs">{label}</p>
                        </button>
                      ))}
                    </div>

                    {/* WhatsApp toggle */}
                    <div className="flex items-center justify-between mt-4 bg-[#1C1F2A] rounded-xl px-4 py-3">
                      <div className="flex items-center gap-2">
                        <MessageCircle className="w-5 h-5 text-[#25D366]" />
                        <span className="text-sm text-white">Send WhatsApp confirmation</span>
                      </div>
                      <button
                        onClick={() => setWaToggle((v) => !v)}
                        className={`relative w-11 h-6 rounded-full transition-colors ${
                          waToggle ? "bg-[#25D366]" : "bg-white/10"
                        }`}
                      >
                        <span
                          className={`absolute top-0.5 w-5 h-5 bg-white rounded-full shadow transition-transform ${
                            waToggle ? "translate-x-5" : "translate-x-0.5"
                          }`}
                        />
                      </button>
                    </div>
                  </div>
                )}
              </motion.div>
            </AnimatePresence>

            {/* Navigation */}
            <div className="flex justify-between mt-6">
              {step > 1 ? (
                <button
                  onClick={() => setStep((s) => s - 1)}
                  className="border border-white/10 text-white px-4 py-2 rounded-lg text-sm hover:border-white/30 transition-colors"
                >
                  Back
                </button>
              ) : (
                <div />
              )}

              {step < 4 ? (
                <button
                  onClick={() => setStep((s) => s + 1)}
                  className="bg-[#2563EB] text-white px-6 py-2 rounded-lg text-sm font-semibold hover:bg-[#2563EB]/90 transition-colors"
                >
                  Next →
                </button>
              ) : (
                <button
                  onClick={handleClose}
                  className="flex items-center gap-2 text-white font-semibold px-6 py-3 rounded-xl text-sm"
                  style={{
                    background: "#2563EB",
                    boxShadow: "0 0 20px rgba(37,99,235,0.4)",
                  }}
                >
                  <Check className="w-4 h-4" />
                  Confirm Booking
                </button>
              )}
            </div>
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  )
}

import { NextResponse } from "next/server";
import { connectDB } from "@/lib/mongodb";
import Invoice from "@/lib/models/Invoice";
import Appointment from "@/lib/models/Appointment";
import Customer from "@/lib/models/Customer";
import Service from "@/lib/models/Service";
import User from "@/lib/models/User";

const TAX_RATE = 0.18;

export async function GET() {
  try {
    await connectDB();
    const invoices = await Invoice.find()
      .populate("customerId", "name phone")
      .populate("branchId", "name")
      .populate("appointmentId", "slot status")
      .populate("lineItems.serviceId", "name duration category")
      .populate("lineItems.staffId", "name");

    return NextResponse.json({ success: true, data: invoices });
  } catch (error) {
    const message = error instanceof Error ? error.message : "Failed to fetch invoices";
    return NextResponse.json({ success: false, error: message }, { status: 500 });
  }
}

export async function POST(request: Request) {
  try {
    await connectDB();
    const body = await request.json();
    const {
      appointmentId,
      customerId,
      branchId,
      lineItems,
      discountType,
      discountValue,
      loyaltyPointsRedeemed,
      paymentMethod,
      paymentSplit,
    } = body ?? {};

    if (!customerId || !branchId || !Array.isArray(lineItems) || lineItems.length === 0) {
      return NextResponse.json(
        { success: false, error: "customerId, branchId, and lineItems are required" },
        { status: 400 }
      );
    }

    const staffIds = [...new Set(lineItems.map((item) => item.staffId).filter(Boolean))];
    const serviceIds = [...new Set(lineItems.map((item) => item.serviceId).filter(Boolean))];

    const [staffList, serviceList] = await Promise.all([
      User.find({ _id: { $in: staffIds } }),
      Service.find({ _id: { $in: serviceIds } }),
    ]);

    const staffMap = new Map(staffList.map((staff) => [staff._id.toString(), staff]));
    const serviceMap = new Map(serviceList.map((service) => [service._id.toString(), service]));

    const normalizedItems = lineItems.map((item) => {
      const staff = item.staffId ? staffMap.get(item.staffId.toString()) : undefined;
      const service = item.serviceId ? serviceMap.get(item.serviceId.toString()) : undefined;
      const commissionRate = staff?.commissionRate ?? 0;
      const price = Number(item.price ?? 0);
      const commissionAmount = Math.round(price * (commissionRate / 100));

      return {
        serviceId: item.serviceId,
        serviceName: service?.name ?? item.serviceName ?? "Service",
        staffId: item.staffId,
        staffName: staff?.name ?? item.staffName ?? "Staff",
        price,
        commissionRate,
        commissionAmount,
      };
    });

    const subtotal = normalizedItems.reduce((sum, item) => sum + item.price, 0);
    const normalizedDiscountValue = Number(discountValue ?? 0);
    const redeemedPoints = Number(loyaltyPointsRedeemed ?? 0);

    let discountAmount = 0;
    if (discountType === "flat") {
      discountAmount = normalizedDiscountValue;
    } else if (discountType === "percentage") {
      discountAmount = Math.round(subtotal * (normalizedDiscountValue / 100));
    } else if (discountType === "loyalty") {
      discountAmount = Math.round(redeemedPoints * 0.5);
    }

    const taxable = subtotal - discountAmount;
    const taxAmount = Math.round(taxable * TAX_RATE);
    const total = taxable + taxAmount;

    const invoice = await Invoice.create({
      appointmentId,
      customerId,
      branchId,
      lineItems: normalizedItems,
      subtotal,
      discountType,
      discountValue: normalizedDiscountValue,
      discountAmount,
      loyaltyPointsRedeemed: redeemedPoints,
      taxRate: TAX_RATE * 100,
      taxAmount,
      total,
      paymentMethod,
      paymentSplit,
      status: "paid",
      sentToWhatsApp: false,
    });

    if (appointmentId) {
      await Appointment.updateOne(
        { _id: appointmentId },
        { $set: { status: "completed", completedAt: new Date() } }
      );
    }

    const earnedPoints = Math.floor(total / 100);
    await Customer.updateOne(
      { _id: customerId },
      { $inc: { totalSpend: total, loyaltyPoints: earnedPoints - redeemedPoints } }
    );

    const populated = await Invoice.findById(invoice._id)
      .populate("customerId", "name phone")
      .populate("branchId", "name")
      .populate("appointmentId", "slot status")
      .populate("lineItems.serviceId", "name duration")
      .populate("lineItems.staffId", "name");

    return NextResponse.json({ success: true, data: populated }, { status: 201 });
  } catch (error) {
    const message = error instanceof Error ? error.message : "Failed to create invoice";
    return NextResponse.json({ success: false, error: message }, { status: 500 });
  }
}

